import { useClosestDimensionPoints } from './useClosestDimensionPoints.js';
import { MouseCoordinate } from '../../core/types/overlays.js';
import { isVertical, isStacked } from '../functions/layout.js';
import { DimensionXYPoint } from '../types/categorical-bar-chart-data.js';
import { GroupMode, Layout } from '../types/categorical-bar-chart.js';
import { getClosestDistance } from '../util/getClosestDistance.js';

/**
 * Retrieve the dimension X/Y point based on the
 * closest category considering the current mouse position, layer and group mode
 *
 * @param layout - layou mode of the chart
 * @param groupMode - group mode of the chart
 * @param mousePosition - mouse coordinate
 * @returns closestpoint and closespoints of the mouse coordinate
 */
export const useClosestDimensionPoint = (
  layout: Layout,
  groupMode: GroupMode = 'stacked',
  mousePosition?: MouseCoordinate,
) => {
  const closestDimensionPoints = useClosestDimensionPoints(
    layout,
    groupMode,
    mousePosition!,
  );

  const closestDimensionPoint = findClosestDimensionPoint(
    layout,
    mousePosition!,
    closestDimensionPoints,
    groupMode,
  );

  return {
    closestDimensionPoint: closestDimensionPoint ?? closestDimensionPoints[0],
    closestDimensionPoints,
  };
};

const findClosestDimensionPoint = (
  layout: Layout,
  mousePosition: MouseCoordinate,
  closestDimensionPoints: DimensionXYPoint[],
  groupMode: GroupMode,
): DimensionXYPoint | undefined => {
  if (mousePosition && closestDimensionPoints.length > 0) {
    const closestDimensionPoint = closestDimensionPoints.reduce((p1, p2) =>
      getClosestDistance(
        mousePosition,
        p1,
        p2,
        isVertical(layout),
        isStacked(groupMode),
      ),
    );

    return closestDimensionPoint;
  }

  return undefined;
};
